@triton.jit
def _slot_pair(a_ptr, b_ptr, n, offs):
    m = offs < n
    a = tl.load(a_ptr + offs, mask=m, other=0)
    b = tl.load(b_ptr + offs, mask=m, other=0)
    # torch.minimum propagates NaN from either operand; request the native
    # NaN-propagating vector minimum instead of an explicit compare/select chain.
    tl.store(a_ptr + offs, tl.minimum(a, b, propagate_nan=tl.PropagateNan.ALL), mask=m)


@triton.jit
def _slot_scalar(a_ptr, n, s, offs):
    m = offs < n
    a = tl.load(a_ptr + offs, mask=m, other=0)
    tl.store(a_ptr + offs, tl.where(a != a, a, tl.minimum(a, s)), mask=m)


@triton.jit
def _k_linear(
    a0,
    b0,
    a1,
    b1,
    a2,
    b2,
    a3,
    b3,
    n0,
    n1,
    n2,
    n3,
    BLOCK: tl.constexpr,
    G: tl.constexpr,
    NITER: tl.constexpr,
    I64: tl.constexpr,
):
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    for k in tl.static_range(NITER):
        t = pid + k * npr
        if I64:
            offs = t.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
        else:
            offs = t * BLOCK + tl.arange(0, BLOCK)
        _slot_pair(a0, b0, n0, offs)
        if G > 1:
            _slot_pair(a1, b1, n1, offs)
        if G > 2:
            _slot_pair(a2, b2, n2, offs)
        if G > 3:
            _slot_pair(a3, b3, n3, offs)


