@triton.jit
def _k_strided(
    a_ptr,
    b_ptr,
    n,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    pa0,
    pa1,
    pa2,
    pa3,
    pa4,
    pa5,
    pa6,
    pa7,
    pb0,
    pb1,
    pb2,
    pb3,
    pb4,
    pb5,
    pb6,
    pb7,
    R: tl.constexpr,
    BLOCK: tl.constexpr,
    NITER: tl.constexpr,
):
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    for k in tl.static_range(NITER):
        t = pid + k * npr
        linear = t.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
        m = linear < n
        rem = linear
        oa = tl.zeros([BLOCK], dtype=tl.int64)
        ob = tl.zeros([BLOCK], dtype=tl.int64)
        if R > 0:
            r0 = rem % d0.to(tl.int64)
            oa = oa + r0 * pa0.to(tl.int64)
            ob = ob + r0 * pb0.to(tl.int64)
            rem = rem // d0.to(tl.int64)
        if R > 1:
            r1 = rem % d1.to(tl.int64)
            oa = oa + r1 * pa1.to(tl.int64)
            ob = ob + r1 * pb1.to(tl.int64)
            rem = rem // d1.to(tl.int64)
        if R > 2:
            r2 = rem % d2.to(tl.int64)
            oa = oa + r2 * pa2.to(tl.int64)
            ob = ob + r2 * pb2.to(tl.int64)
            rem = rem // d2.to(tl.int64)
        if R > 3:
            r3 = rem % d3.to(tl.int64)
            oa = oa + r3 * pa3.to(tl.int64)
            ob = ob + r3 * pb3.to(tl.int64)
            rem = rem // d3.to(tl.int64)
        if R > 4:
            r4 = rem % d4.to(tl.int64)
            oa = oa + r4 * pa4.to(tl.int64)
            ob = ob + r4 * pb4.to(tl.int64)
            rem = rem // d4.to(tl.int64)
        if R > 5:
            r5 = rem % d5.to(tl.int64)
            oa = oa + r5 * pa5.to(tl.int64)
            ob = ob + r5 * pb5.to(tl.int64)
            rem = rem // d5.to(tl.int64)
        if R > 6:
            r6 = rem % d6.to(tl.int64)
            oa = oa + r6 * pa6.to(tl.int64)
            ob = ob + r6 * pb6.to(tl.int64)
            rem = rem // d6.to(tl.int64)
        if R > 7:
            r7 = rem % d7.to(tl.int64)
            oa = oa + r7 * pa7.to(tl.int64)
            ob = ob + r7 * pb7.to(tl.int64)
        a = tl.load(a_ptr + oa, mask=m, other=0)
        b = tl.load(b_ptr + ob, mask=m, other=0)
        r = tl.minimum(a, b, propagate_nan=tl.PropagateNan.ALL)
        tl.store(a_ptr + oa, r, mask=m)


@triton.jit
def _k_strided_s(
    a_ptr,
    n,
    s,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    pa0,
    pa1,
    pa2,
    pa3,
    pa4,
    pa5,
    pa6,
    pa7,
    R: tl.constexpr,
    BLOCK: tl.constexpr,
    NITER: tl.constexpr,
):
    pid = tl.program_id(0)
    npr = tl.num_programs(0)
    for k in tl.static_range(NITER):
        t = pid + k * npr
        linear = t.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
        m = linear < n
        rem = linear
        oa = tl.zeros([BLOCK], dtype=tl.int64)
        if R > 0:
            oa = oa + (rem % d0.to(tl.int64)) * pa0.to(tl.int64)
            rem = rem // d0.to(tl.int64)
        if R > 1:
            oa = oa + (rem % d1.to(tl.int64)) * pa1.to(tl.int64)
            rem = rem // d1.to(tl.int64)
        if R > 2:
            oa = oa + (rem % d2.to(tl.int64)) * pa2.to(tl.int64)
            rem = rem // d2.to(tl.int64)
        if R > 3:
            oa = oa + (rem % d3.to(tl.int64)) * pa3.to(tl.int64)
            rem = rem // d3.to(tl.int64)
        if R > 4:
            oa = oa + (rem % d4.to(tl.int64)) * pa4.to(tl.int64)
            rem = rem // d4.to(tl.int64)
        if R > 5:
            oa = oa + (rem % d5.to(tl.int64)) * pa5.to(tl.int64)
            rem = rem // d5.to(tl.int64)
        if R > 6:
            oa = oa + (rem % d6.to(tl.int64)) * pa6.to(tl.int64)
            rem = rem // d6.to(tl.int64)
        if R > 7:
            oa = oa + (rem % d7.to(tl.int64)) * pa7.to(tl.int64)
        a = tl.load(a_ptr + oa, mask=m, other=0)
        tl.store(a_ptr + oa, tl.where(a != a, a, tl.minimum(a, s)), mask=m)


# --------------------------------------------------------------------------- #
# host side helpers
# --------------------------------------------------------------------------- #
def _shape_error(a, b):
    return RuntimeError(
        "output with shape %s doesn't match the broadcast shape %s"
        % (tuple(a.shape), tuple(b.shape))
    )


def _pair_plan(a, b):
    """Plan one (self, other) pair.

    Returns ("L", n) when both operands can be walked with matching unit
    strides, otherwise ("S", (shape, self_strides, other_strides)) with the
    iteration dims ordered by self's stride (ascending) and collapsed.
    """
    n = a.numel()
    if a.shape == b.shape and a.is_contiguous() and b.is_contiguous():
        return ("L", n)

    adim = a.dim()
    bdim = b.dim()
    if bdim > adim:
        raise _shape_error(a, b)
    bshape = b.shape
    bstride = b.stride()

    dims = []
    for k in range(adim):
        sa = a.size(k)
        j = k - (adim - bdim)
        if j < 0:
            if sa != 1:
                raise _shape_error(a, b)
            continue
        sb = bshape[j]
        if sa == 1:
            if sb != 1:
                raise _shape_error(a, b)
            continue
        if sb == 1:
            pbs = 0
        elif sb == sa:
            pbs = bstride[j]
        else:
            raise _shape_error(a, b)
        dims.append((a.stride(k), sa, pbs))

    if not dims:
        return ("L", 1)

    dims.sort(key=lambda d: d[0])

    merged = []
    for pas, sz, pbs in dims:
        if merged:
            mpas, msz, mpbs = merged[-1]
            if mpas * msz == pas and mpbs * msz == pbs:
                merged[-1] = (mpas, msz * sz, mpbs)
                continue
        merged.append((pas, sz, pbs))

    exp = 1
    linear = True
    for pas, sz, pbs in merged:
        if pas != exp or pbs != exp:
            linear = False
            break
        exp *= sz
    if linear:
        return ("L", exp)

    shape = [m[1] for m in merged]
    sa = [m[0] for m in merged]
    sb = [m[2] for m in merged]
    return ("S", (shape, sa, sb))


def _block_for(max_n, g, esize):
    """Tile size policy.

    Small calls are launch-bound, so the tile only has to be cheap.  Large
    calls are bound by a per-tile fixed cost on top of an already
    reference-class streaming rate, so the tile is chosen from a bytes budget
    (about 16 KiB per stream per tile) to keep the tile count low.
    """
    if max_n <= 1024:
        return 1024
    if max_n <= 65536:
        return 4096 if g <= 2 else 2048
    # bandwidth-bound regime: 2*G live tile buffers must fit the 192 KiB
    # unified buffer, i.e. about 16 KiB per stream per tile.
    return 8192 if esize <= 2 else 4096


def _grid_for(ntiles):
    grid = ntiles if ntiles < _MAX_GRID else _MAX_GRID
    if grid < 1:
        grid = 1
    niter = (ntiles + grid - 1) // grid
    return grid, niter


def _launch_linear(pairs):
    """pairs: sequence of (a, b, n) walked with matching unit strides."""
    total = len(pairs)
    i = 0
    while i < total:
        grp = pairs[i : i + _MAX_GROUP]
        g = len(grp)
        a0, b0, n0 = grp[0]
        if g > 1:
            a1, b1, n1 = grp[1]
        else:
            a1, b1, n1 = a0, b0, n0
        if g > 2:
            a2, b2, n2 = grp[2]
        else:
            a2, b2, n2 = a0, b0, n0
        if g > 3:
            a3, b3, n3 = grp[3]
        else:
            a3, b3, n3 = a0, b0, n0
        mx = n0
        if n1 > mx:
            mx = n1
        if n2 > mx:
            mx = n2
        if n3 > mx:
            mx = n3
        if mx > 65536:
            es = a0.element_size()
            if g > 1:
                es = max(es, a1.element_size())
            if g > 2:
                es = max(es, a2.element_size())
            if g > 3:
                es = max(es, a3.element_size())
            block = _block_for(mx, g, es)
        else:
            block = _block_for(mx, g, 4)
        ntiles = (mx + block - 1) // block
        if mx > 65536 and ntiles <= _MAX_GRID:
            # two consecutive tiles per program: same tile footprint, half the
            # program dispatches
            grid = (ntiles + 1) // 2
            niter = 2
        else:
            grid, niter = _grid_for(ntiles)
        _k_linear[(grid,)](
            a0,
            b0,
            a1,
            b1,
            a2,
            b2,
            a3,
            b3,
            n0,
            n1,
            n2,
            n3,
            BLOCK=block,
            G=g,
            NITER=niter,
            I64=(mx > 0x7FFFFFFF),
        )
        i += g


def _launch_strided(a, b, plan):
    shape, sa, sb = plan
    rank = len(shape)
    if rank > _MAX_RANK:
        _peel(a, b)
        return
    n = a.numel()
    block = 1024 if n <= 1024 else 2048
    ntiles = (n + block - 1) // block
    grid, niter = _grid_for(ntiles)
    pad_d = list(shape) + [1] * (_MAX_RANK - rank)
    pad_a = list(sa) + [0] * (_MAX_RANK - rank)
    pad_b = list(sb) + [0] * (_MAX_RANK - rank)
    _k_strided[(grid,)](
        a,
        b,
        n,
        *pad_d,
        *pad_a,
        *pad_b,
        R=rank,
        BLOCK=block,
        NITER=niter,
    )


def _launch_strided_scalar(a, s, plan):
    shape, sa = plan
    rank = len(shape)
    n = a.numel()
    block = 1024 if n <= 1024 else 2048
    ntiles = (n + block - 1) // block
    grid, niter = _grid_for(ntiles)
    pad_d = list(shape) + [1] * (_MAX_RANK - rank)
    pad_a = list(sa) + [0] * (_MAX_RANK - rank)
    _k_strided_s[(grid,)](
        a,
        n,
        s,
        *pad_d,
        *pad_a,
        R=rank,
        BLOCK=block,
        NITER=niter,
    )


def _peel(a, b):
    """Rank > _MAX_RANK: walk the outermost iteration dim from the host."""
    dim = max(range(a.dim()), key=lambda k: a.stride(k))
    for idx in range(a.size(dim)):
        sub_a = a.narrow(dim, idx, 1).squeeze(dim)
        sub_b = b.narrow(dim, idx, 1).squeeze(dim)
        _run_pair(sub_a, sub_b)


def _run_pair(a, b):
    if a.numel() == 0:
        return
    kind, payload = _pair_plan(a, b)
    if kind == "L":
        _launch_linear([(a, b, payload)])
    else:
        _launch_strided(a, b, payload)


# --------------------------------------------------------------------------- #
# scalar (single number / number list) support
# --------------------------------------------------------------------------- #
def _cast_scalar(value, dtype):
    if dtype.is_floating_point:
        return float(value)
    if dtype == torch.bool:
        return bool(value)
    return int(value)


def _launch_linear_scalar(items):
    total = len(items)
    i = 0
    while i < total:
        grp = items[i : i + _MAX_GROUP]
        g = len(grp)
        a0, s0, n0 = grp[0]
        a1, s1, n1 = grp[1] if g > 1 else grp[0]
        a2, s2, n2 = grp[2] if g > 2 else grp[0]
        a3, s3, n3 = grp[3] if g > 3 else grp[0]
        mx = n0
        if n1 > mx:
            mx = n1
        if n2 > mx:
            mx = n2
        if n3 > mx:
            mx = n3
        if mx > 65536:
            es = a0.element_size()
            if g > 1:
                es = max(es, a1.element_size())
            if g > 2:
                es = max(es, a2.element_size())
            if g > 3:
                es = max(es, a3.element_size())
            block = _block_for(mx, g, es)
        else:
            block = _block_for(mx, g, 4)
        ntiles = (mx + block - 1) // block
        grid, niter = _grid_for(ntiles)
        _k_linear_s[(grid,)](
            a0,
            a1,
            a2,
            a3,
            n0,
            n1,
            n2,
            n3,
            s0,
            s1,
            s2,
            s3,
            BLOCK=block,
            G=g,
            NITER=niter,
            I64=(mx > 0x7FFFFFFF),
        )
        i += g


def _scalar_plan(a):
    """Plan for a single tensor against a scalar."""
    n = a.numel()
    if a.is_contiguous():
        return ("L", n)
    dims = []
    for k in range(a.dim()):
        if a.size(k) == 1:
            continue
        dims.append((a.stride(k), a.size(k)))
    if not dims:
        return ("L", 1)
    dims.sort(key=lambda d: d[0])
    merged = []
    for pas, sz in dims:
        if merged:
            mpas, msz = merged[-1]
            if mpas * msz == pas:
                merged[-1] = (mpas, msz * sz)
                continue
        merged.append((pas, sz))
    exp = 1
    for pas, sz in merged:
        if pas != exp:
            break
        exp *= sz
    else:
        return ("L", exp)
    return ("S", ([m[1] for m in merged], [m[0] for m in merged]))


def _run_scalar_list(tensors, others):
    count = len(tensors)
    if len(others) != count:
        raise RuntimeError(
            "Tensor lists must have the same number of tensors, got %d and %d"
            % (count, len(others))
        )
    if count == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    pending = []
    for i in range(count):
        a = tensors[i]
        if a.numel() == 0:
            continue
        s = _cast_scalar(others[i], a.dtype)
        kind, payload = _scalar_plan(a)
        if kind == "L":
            pending.append((a, s, payload))
            if len(pending) == _MAX_GROUP:
                _launch_linear_scalar(pending)
                pending = []
        else:
            if pending:
                _launch_linear_scalar(pending)
                pending = []
            _launch_strided_scalar(a, s, payload)
    if pending:
        _launch_linear_scalar(pending)


def _run_tensor_list(tensors, others):
    count = len(tensors)
    if len(others) != count:
        raise RuntimeError(
            "Tensor lists must have the same number of tensors, got %d and %d"
            % (count, len(others))
        )
    if count == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    # Fast path: matched contiguous pairs (the common case) -> fused launches.
    pairs = []
    for i in range(count):
        a = tensors[i]
        b = others[i]
        if not (a.shape == b.shape and a.is_contiguous() and b.is_contiguous()):
            pairs = None
            break
        n = a.numel()
        if n:
            pairs.append((a, b, n))

    if pairs is not None:
        if pairs:
            _launch_linear(pairs)
        return

    pending = []
    for i in range(count):
        a = tensors[i]
        b = others[i]
        if a.numel() == 0:
            continue
        kind, payload = _pair_plan(a, b)
        if kind == "L":
            pending.append((a, b, payload))
            if len(pending) == _MAX_GROUP:
                _launch_linear(pending)
                pending = []
        else:
            if pending:
                _launch_linear(pending)
                pending = []
            _launch_strided(a, b, payload)
    if pending:
        _launch_linear(pending)


# --------------------------------------------------------------------------- #
# entry point
# --------------------------------------------------------------------------- #
def foreach_minimum_list_(self, other):
    kind = type(other)
    if kind is list:
        # Inlined hot path: four matched contiguous pairs (the benchmark form).
        if len(other) == 4 and len(self) == 4 and torch.is_tensor(other[0]):
            a0 = self[0]
            b0 = other[0]
            if a0.is_contiguous() and b0.is_contiguous() and a0.shape == b0.shape:
                a1 = self[1]
                b1 = other[1]
                a2 = self[2]
                b2 = other[2]
                a3 = self[3]
                b3 = other[3]
                n = a0.numel()
                if (
                    n > 0
                    and a1.numel() == n
                    and a2.numel() == n
                    and a3.numel() == n
                    and a1.is_contiguous()
                    and b1.is_contiguous()
                    and a2.is_contiguous()
                    and b2.is_contiguous()
                    and a3.is_contiguous()
                    and b3.is_contiguous()
                    and a1.shape == b1.shape
                    and a2.shape == b2.shape
                    and a3.shape == b3.shape
                ):
                    if n > 65536:
                        es = a0.element_size()
                        if a1.element_size() > es:
                            es = a1.element_size()
                        if a2.element_size() > es:
                            es = a2.element_size()
                        if a3.element_size() > es:
                            es = a3.element_size()
                        block = 8192 if es <= 2 else 4096
                    elif n > 1024:
                        block = 2048
                    else:
                        block = 1024
                    ntiles = (n + block - 1) // block
                    if n > 65536 and ntiles <= _MAX_GRID:
                        grid = (ntiles + 1) // 2
                        niter = 2
                    else:
                        niter = 1
                        grid = ntiles
                    _k_linear[(grid,)](
                        a0,
                        b0,
                        a1,
                        b1,
                        a2,
                        b2,
                        a3,
                        b3,
                        n,
                        n,
                        n,
                        n,
                        block,
                        4,
                        niter,
                        n > 0x7FFFFFFF,
                    )
                    return None
        if other and not torch.is_tensor(other[0]):
            _run_scalar_list(self, other)
        else:
            _run_tensor_list(self, other)
    elif kind is tuple:
        if other and not torch.is_tensor(other[0]):
            _run_scalar_list(self, other)
        else:
            _run_tensor_list(self, other)
    else:
        _run_scalar_list(self, [other] * len(self))
    return None
